package com.aetherforge.security;
import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import java.time.*;import java.util.*;import java.util.concurrent.ConcurrentHashMap;
@Service public class TokenService {public record Principal(String email,String role,Instant expiresAt){}private final Map<String,Principal> tokens=new ConcurrentHashMap<>();private final long ttl;public TokenService(@Value("${aetherforge.token-ttl-minutes:480}")long ttl){this.ttl=ttl;}public String issue(String email,String role){var t=UUID.randomUUID().toString();tokens.put(t,new Principal(email,role,Instant.now().plus(ttl,java.time.temporal.ChronoUnit.MINUTES)));return t;}public Principal resolve(String token){var p=tokens.get(token);if(p==null)return null;if(p.expiresAt().isBefore(Instant.now())){tokens.remove(token);return null;}return p;}public void revoke(String token){tokens.remove(token);}}
